begin; set transaction read only; set local statement_timeout='30s';
select jsonb_build_object(
 'database_version',current_setting('server_version'),
 'migration_count',(select count(*) from supabase_migrations.schema_migrations),
 'client_rpc_count',122,
 'missing_client_rpcs',(select coalesce(jsonb_agg(r),'[]'::jsonb) from unnest(array['acknowledge_move_out_settlement','activate_tenant_contract','add_room_inspection_finding','append_confidential_report_addendum','apply_billing_charge_action','apply_owner_rent_rate_override','approve_employee_curfew_profile','assign_tenant_bed','cancel_eviction_case','cancel_move_out_case','cancel_my_maintenance_report','cancel_room_inspection','cancel_room_transfer','claim_onboarding_invitation','cleanup_my_expired_notifications','close_eviction_case','complete_onboarding_invitation','complete_room_inspection','complete_room_transfer','create_additional_charge','create_conduct_case','create_employee_curfew_profile','create_move_out_case','create_room_floor','create_room_inspection','create_room_with_four_beds','create_utility_charge','create_utility_charge_cart','current_user_role','decide_conduct_case_appeal','end_tenant_assignment','get_move_out_charge_preview','get_my_conduct_case_responses','get_my_conduct_case_warnings','get_my_conduct_cases','get_my_contract','get_my_contract_for_signing','get_my_editable_profile','get_my_guardian_alert_preferences','get_my_room_cleaning_schedule','get_my_room_details','get_my_user_preferences','get_or_create_direct_staff_conversation','get_unassigned_security_deposits','issue_conduct_case_warning','link_legacy_security_deposit','list_confidential_report_addenda','list_confidential_reports_v2','list_maintenance_room_locations','list_messaging_staff','list_move_out_deductible_charges','list_my_direct_staff_conversations','manage_room_floor','mark_all_notifications_read','mark_conversation_messages_read','mark_move_out_ready_for_closure','mark_notification_read','my_unread_notification_count','owner_review_confidential_report','propose_move_out_charge_deduction','propose_room_transfer','publish_conduct_case','publish_eviction_notice','publish_room_transfer','recommend_conduct_termination_review','record_eviction_decision','record_eviction_departure','record_move_out_settlement_with_charges','record_security_deposit_receipt','record_staff_manual_log','record_staff_payment','record_tenant_geofence_check','record_tenant_geofence_transition','regenerate_cleaning_schedule','register_conduct_case_evidence','register_current_push_device','register_room_inspection_evidence','rename_room_floor','renew_tenant_contract','reschedule_visitor_request','resolve_employee_curfew_profile','respond_to_eviction_notice','review_contract_requirement','review_move_out_deduction','review_payment_transaction','review_room_transfer_signature','review_signed_contract_document','revoke_employee_curfew_profile','safe_delete_room','safe_delete_room_floor','schedule_move_out_final_inspection','set_cleaning_schedule','set_conduct_case_review_status','set_contract_requirement_required','set_move_out_clearance_item','set_move_out_deposit_received','sign_room_transfer','start_conduct_case_appeal_review','start_room_inspection','submit_cleaning_noncompliance_report','submit_conduct_case_appeal','submit_conduct_case_response','submit_contract_requirement','submit_curfew_request','submit_owner_electronic_signature','submit_payment_transaction','submit_tenant_electronic_signature','submit_tenant_onboarding_details','sync_current_email_verification','transition_visitor_request','update_cleaning_noncompliance_report','update_contract_signer','update_dorm_boundary_config','update_dorm_gate_config','update_employee_curfew_profile','update_my_editable_profile','update_my_guardian_alert_preferences','update_my_user_preferences','update_retention_policy_setting','update_room_inspection_finding','update_staff_maintenance','withdraw_conduct_case_appeal']) r where not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=r)),
 'public_table_count',(select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p')),
 'tables_without_rls',(select coalesce(jsonb_agg(c.relname),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p') and not c.relrowsecurity),
 'anon_select_tables',(select coalesce(jsonb_agg(c.relname),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p') and has_table_privilege('anon',c.oid,'SELECT')),
 'anonymous_policies',(select coalesce(jsonb_agg(jsonb_build_object('table',tablename,'name',policyname,'command',cmd,'condition',qual,'check',with_check)),'[]'::jsonb) from pg_policies where schemaname='public' and (roles @> array['anon']::name[] or roles @> array['public']::name[])),
 'definer_functions_without_search_path',(select coalesce(jsonb_agg(p.proname),'[]'::jsonb) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prosecdef and not exists(select 1 from unnest(coalesce(p.proconfig,array[]::text[])) x where x like 'search_path=%')),
 'unvalidated_constraints',(select coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'constraint',co.conname)),'[]'::jsonb) from pg_constraint co join pg_class c on c.oid=co.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not co.convalidated),
 'disabled_triggers',(select coalesce(jsonb_agg(t.tgname),'[]'::jsonb) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal and t.tgenabled='D'),
 'invalid_indexes',(select coalesce(jsonb_agg(c.relname),'[]'::jsonb) from pg_index i join pg_class c on c.oid=i.indexrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not i.indisvalid),
 'storage_buckets',(select jsonb_agg(jsonb_build_object('name',id,'public',public,'max_bytes',file_size_limit)) from storage.buckets),
 'realtime_tables',(select jsonb_agg(tablename) from pg_publication_tables where pubname='supabase_realtime'),
 'cron_catalog_present',to_regclass('cron.job') is not null
) as audit;
rollback;
